      "name": "k8s/deployment.yaml",
      "content": "apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: auroratech-mlops-api\n  labels:\n    app: auroratech-ml-api\nspec:\n  replicas: 2\n  selector:\n    matchLabels:\n      app: auroratech-ml-api\n  template:\n    metadata:\n      labels:\n        app: auroratech-ml-api\n    spec:\n      containers:\n      - name: api\n        image: auroratech/margin-predictor:latest\n        imagePullPolicy: Always\n        ports:\n        - containerPort: 8000\n        env:\n        - name: ENV\n          value: \"production\"\n        resources:\n          limits:\n            memory: \"512Mi\"\n            cpu: \"500m\"\n          requests:\n            memory: \"256Mi\"\n            cpu: \"250m\"\n        livenessProbe:\n          httpGet:\n            path: /health\n            port: 8000\n          initialDelaySeconds: 15\n          periodSeconds: 20\n---\napiVersion: v1\nkind: Service\nmetadata:\n  name: auroratech-mlops-api-svc\nspec:\n  type: ClusterIP\n  ports:\n  - port: 80\n    targetPort: 8000\n  selector:\n    app: auroratech-ml-api\n",
