      "name": "monitoring/drift_config.yaml",
      "content": "drift_detection:\n  features:\n    - eur_to_usd\n    - eur_to_twd\n    - component_delay_days\n    - freight_cost_eur\n  metrics:\n    - ks_stat\n    - wasserstein_distance\n  threshold: 0.05\n  action: trigger_retrain\n",
